<script setup lang="ts">
import {computed,ref} from 'vue';import {api,duration,type Worker,type State} from '../api';import {Plus,Users,Clock,Check,X,Save} from 'lucide-vue-next';
const props=defineProps<{workers:Worker[];state:State}>();const emit=defineEmits<{refresh:[];selectTask:[id:string]}>();
const editing=ref(false),creating=ref(false),busy=ref(false),error=ref(''),selected=ref('');
const form=ref({username:'',displayName:'',phone:'',area:'',password:'',enabled:true});
const selectedWorker=computed(()=>props.workers.find(w=>w.username===selected.value));
const tasks=computed(()=>props.state.tasks.filter(t=>t.worker===selected.value));
function edit(w?:Worker){creating.value=!w;form.value=w?{username:w.username,displayName:w.displayName,phone:w.phone||'',area:w.area||'',password:'',enabled:w.enabled}:{username:'',displayName:'',phone:'',area:'',password:'',enabled:true};editing.value=true;error.value='';}
async function save(){busy.value=true;error.value='';try{await api(creating.value?'/workers':'/workers/'+form.value.username,form.value,creating.value?'POST':'PUT');editing.value=false;emit('refresh');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><div><div class="workspace-toolbar"><div><h3>人员与片区</h3><small>管理作业账号、片区、任务与反馈</small></div><button class="primary" @click="edit()"><Plus :size="17"/>新增工作人员</button></div><div class="worker-grid"><article v-for="w in workers" :key="w.username" class="panel worker-card" :class="{chosen:selected===w.username}"><div class="worker-top"><span class="worker-avatar">{{w.displayName.slice(-2)}}</span><div><h3>{{w.displayName}}</h3><small>{{w.username}} · {{w.area||'待分配片区'}}</small></div><span class="badge">{{w.enabled?'已启用':'已停用'}}</span></div><div class="worker-stats"><div><strong>{{w.tasks}}</strong><small>累计任务</small></div><div><strong>{{w.running}}</strong><small>正在执行</small></div><div><strong>{{w.openAlerts}}</strong><small>待处理告警</small></div></div><p class="worked"><Clock :size="16"/>累计巡检 {{duration(w.workedSeconds)}}</p><div class="worker-actions"><button class="text-btn" @click="selected=w.username">查看任务与反馈</button><button class="text-btn" @click="edit(w)">编辑资料</button></div></article></div><section v-if="selectedWorker" class="panel worker-history"><div class="panel-heading"><h3>{{selectedWorker.displayName}} · 作业记录</h3><button @click="selected=''" aria-label="关闭人员记录"><X :size="18"/></button></div><div v-if="!tasks.length" class="empty">暂无分配任务</div><div v-for="t in tasks" :key="t.id" class="worker-task" @click="emit('selectTask',t.id)"><div><strong>{{t.name}}</strong><small>{{t.id}} · {{t.start}} → {{t.end}}</small></div><div><strong>{{duration(t.workedSeconds+(t.resumedAt?(Date.now()-Date.parse(t.resumedAt))/1000:0))}}</strong><small>{{t.startedAt?new Date(t.startedAt).toLocaleString():'尚未开始'}}</small></div><span class="text-btn">查看详情 →</span></div></section><Teleport to="body"><div v-if="editing" class="modal-backdrop" @click.self="editing=false"><form class="modal" @submit.prevent="save"><div class="panel-heading"><h3>{{creating?'新增工作人员':'编辑工作人员'}}</h3><button type="button" @click="editing=false" aria-label="关闭"><X :size="20"/></button></div><div class="form-body"><div v-if="error" class="error">{{error}}</div><label>登录账号<input v-model="form.username" :readonly="!creating" pattern="[A-Za-z0-9_-]{3,30}" required/></label><label>姓名<input v-model="form.displayName" maxlength="60" required/></label><div class="dual"><label>负责片区<input v-model="form.area" maxlength="100"/></label><label>联系方式<input v-model="form.phone" maxlength="40"/></label></div><label>{{creating?'初始密码':'重置密码（留空保持原密码）'}}<input v-model="form.password" type="password" :required="creating" minlength="8" maxlength="100" autocomplete="new-password"/></label><label v-if="!creating" class="check-label"><input v-model="form.enabled" type="checkbox"/>启用账号</label><button class="primary" :disabled="busy"><Save :size="16"/>保存工作人员</button></div></form></div></Teleport></div></template>
